# Intermediate unit 67 – Crime. Bám sách: trang 138–139 (đã xem ảnh trang) + đáp án + Mini dictionary. Không chép nguyên văn.
# break-in (u4), breakout (u66), take sb in = lừa (u5) đã có thẻ cùng nghĩa → chỉ nhắc.
# Nghĩa mới: break out (vượt ngục), hold up / hold-up (cướp; u23 = trì hoãn) → thẻ có sense.
theory = (
 H("A", "Crime reports in newspapers", "Tin tội phạm trên báo")
 + P("People retell four news stories in everyday phrasal verbs: a guard punched and kicked by thieves was <b>beaten up</b> (hurt by repeated blows); thieves who forced their way into a jeweller’s <b>broke into</b> it; three prisoners who escaped have <b>broken out</b> of jail; two men who tricked a teacher and took six school computers <b>walked off with</b> them (stole them).",
     "Bốn mẩu tin được kể lại bằng phrasal verb thường ngày: người bảo vệ bị trộm đấm đá là bị <b>beaten up</b> (đánh nhừ tử); kẻ trộm phá cửa vào tiệm kim hoàn là <b>broke into</b> tiệm; ba tù nhân trốn trại đã <b>broken out</b> khỏi nhà tù; hai gã lừa cô giáo rồi lấy sáu máy tính của trường đã <b>walked off with</b> chúng (cuỗm đi).")
 + H("B", "Other verbs connected with crime", "Các động từ khác về tội phạm")
 + T([
   ("hold sb/sth up", "rob a bank, person or vehicle with violence or threats", "cướp (có vũ lực)"),
   ("hack into sth", "enter someone’s computer system illegally", "xâm nhập trái phép (máy tính)"),
   ("tip sb off", "secretly warn someone so they can act", "mật báo"),
   ("put sb up to sth", "encourage someone to do something stupid or wrong", "xúi giục"),
   ("take sb in", "deceive someone (card in Unit 5)", "lừa (đã có thẻ ở bài 5)"),
   ("lead sb on", "make someone believe something false, often to get them to do something", "dụ dỗ, lừa phỉnh"),
   ("let sb off", "not punish someone, or punish them lightly", "tha, xử nhẹ"),
   ("lean on sb", "pressure someone with threats or persuasion (informal)", "gây sức ép"),
   ("be/get mixed up in sth", "be or become involved in something illegal or bad", "dính líu"),
 ])
 + NOTE("<b>Exercise 67.4</b> – nouns in headlines: a <i>hold-up</i> (robbery), a <i>tip-off</i> (secret warning), <i>break-ins</i> (burglaries – card in Unit 4), a <i>breakout</i> (escape – card in Unit 66).",
        "<b>Bài 67.4</b> – danh từ trên tít báo: <i>hold-up</i> (vụ cướp), <i>tip-off</i> (tin mật báo), <i>break-ins</i> (vụ đột nhập – đã có thẻ ở bài 4), <i>breakout</i> (vượt ngục – đã có thẻ ở bài 66).")
)
